const encabezado = (nombre) => $json.headers?.[nombre] ?? $json.headers?.[nombre.toLowerCase()] ?? $json[nombre] ?? $json[nombre.toLowerCase()] ?? '';
const extraerCorreo = (valor) => {
  const texto = Array.isArray(valor) ? valor.join(', ') : String(valor ?? '');
  const coincidencia = texto.match(/<([^>]+)>/) || texto.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return String(coincidencia?.[1] ?? coincidencia?.[0] ?? texto).trim().toLowerCase();
};
const adjuntos = Object.entries($binary ?? {}).map(([campo, archivo]) => ({
  campo,
  nombre: archivo.fileName ?? campo,
  mime_type: archivo.mimeType ?? null,
  tamano_bytes: archivo.fileSize ?? null,
}));
const messageId = String($json.id ?? $json.messageId ?? encabezado('Message-ID')).trim();
if (!messageId) throw new Error('Gmail no entregó un identificador para deduplicar el correo.');
return [{ json: {
  messageId,
  threadId: String($json.threadId ?? '').trim() || null,
  remitente: extraerCorreo($json.from?.value?.[0]?.address ?? encabezado('From')),
  destinatarios: [extraerCorreo(encabezado('To'))].filter(Boolean),
  asunto: String($json.subject ?? encabezado('Subject') ?? '').trim(),
  cuerpo: String($json.textPlain ?? $json.text ?? $json.snippet ?? '').trim(),
  recibidoAt: $json.date ?? $json.internalDate ?? $now.toISO(),
  adjuntos,
}}];

