const correo = $('Normalizar correo').item.json;
const datos = $json.data;
const porClave = new Map();
for (const participacion of datos?.solicitud_proveedores ?? []) {
  porClave.set(`${participacion.solicitud_id}:${participacion.proveedor_id}`, participacion);
}
for (const envio of datos?.envios_solicitud ?? []) {
  const clave = `${envio.solicitud_id}:${envio.proveedor_id}`;
  const coincideHilo = correo.threadId && envio.gmail_thread_id === correo.threadId;
  if (!porClave.has(clave) || coincideHilo) {
    porClave.set(clave, {
      solicitud_id: envio.solicitud_id,
      proveedor_id: envio.proveedor_id,
      estado_respuesta: envio.participacion_seguimiento?.estado_respuesta ?? 'no_envio_cotizacion',
      detalle_respuesta: envio.participacion_seguimiento?.detalle_respuesta ?? 'sin_respuesta',
      numero_coordinaciones: envio.participacion_seguimiento?.numero_coordinaciones ?? 0,
      considerado: envio.participacion_seguimiento?.considerado ?? true,
      aclaraciones_pendientes: envio.participacion_seguimiento?.aclaraciones_pendientes ?? [],
      proveedor_asociado: envio.proveedor_asociado,
      solicitud_cotizacion: envio.solicitud_cotizacion,
      coincidencia_hilo: Boolean(coincideHilo),
    });
  }
}
const candidatos = [...porClave.values()].sort((a, b) => Number(b.coincidencia_hilo) - Number(a.coincidencia_hilo));
if (!candidatos.length) return [];
const prompt = `Analiza una respuesta de proveedor de CostFlow. Devuelve solamente JSON válido.
Debes identificar a cuál candidato corresponde. Prioriza coincidencia_hilo; como respaldo usa correo, razón social, asunto, código, proyecto y contexto previo.
Estados permitidos: no_envio_cotizacion, envio_cotizacion_con_aclaracion, envio_cotizacion.
Usa envio_cotizacion únicamente cuando exista evidencia de versión definitiva y no haya aclaraciones abiertas.
Si existe cotización con consultas o faltantes usa envio_cotizacion_con_aclaracion.
Si solo confirma, consulta, rechaza o no adjunta/ofrece cotización usa no_envio_cotizacion.
Detalles permitidos: sin_respuesta, confirmo_recepcion, consulta_previa, rechazo_participar, aclaraciones_pendientes, cotizacion_definitiva.
Devuelve: solicitudId, proveedorId, estado, detalle, esVersionFinal, aclaraciones (array de textos), evidencia (array de textos), confianza (0 a 1), razon.

CORREO NUEVO:
${JSON.stringify(correo)}

CANDIDATOS:
${JSON.stringify(candidatos)}

HISTORIAL:
${JSON.stringify(datos?.correos_proveedor ?? [])}`;
return [{ json: { ...correo, candidatos, prompt } }];

const contexto = $('Preparar contexto').item.json;
let salida = $json.output ?? $json.text ?? $json;
if (typeof salida === 'string') {
  salida = salida.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
  salida = JSON.parse(salida);
}
const estados = new Set(['no_envio_cotizacion', 'envio_cotizacion_con_aclaracion', 'envio_cotizacion']);
const detalles = new Set(['sin_respuesta', 'confirmo_recepcion', 'consulta_previa', 'rechazo_participar', 'aclaraciones_pendientes', 'cotizacion_definitiva']);
const candidato = contexto.candidatos.find((item) => item.solicitud_id === salida.solicitudId && item.proveedor_id === salida.proveedorId);
if (!candidato) throw new Error('El agente no pudo asociar el correo con una solicitud y proveedor válidos.');
if (!estados.has(salida.estado) || !detalles.has(salida.detalle)) throw new Error('El agente devolvió una clasificación no permitida.');
const paresValidos = {
  envio_cotizacion: new Set(['cotizacion_definitiva']),
  envio_cotizacion_con_aclaracion: new Set(['aclaraciones_pendientes']),
  no_envio_cotizacion: new Set(['sin_respuesta', 'confirmo_recepcion', 'consulta_previa', 'rechazo_participar']),
};
if (!paresValidos[salida.estado].has(salida.detalle)) throw new Error('El estado y el detalle propuestos no son coherentes.');
const confianza = Math.max(0, Math.min(1, Number(salida.confianza ?? 0)));
const fechaCorreo = new Date(contexto.recibidoAt).toLocaleDateString('en-CA', { timeZone: 'America/Lima' });
const fueraPlazo = fechaCorreo > candidato.solicitud_cotizacion.fecha_limite;
const requiereRevision = confianza < 0.8;
const aclaraciones = Array.isArray(salida.aclaraciones) ? salida.aclaraciones.filter(Boolean) : [];
if (salida.estado === 'envio_cotizacion' && aclaraciones.length) throw new Error('Una cotización definitiva no puede contener aclaraciones pendientes.');
const solicitudActiva = candidato.solicitud_cotizacion.estado === 'inicio';
const proveedorActivo = candidato.considerado !== false;
const aplicar = solicitudActiva && proveedorActivo && !fueraPlazo && !requiereRevision;
const evidencia = Array.isArray(salida.evidencia) ? salida.evidencia.filter(Boolean) : [];
const notificar = solicitudActiva && proveedorActivo && !fueraPlazo;
const titulo = requiereRevision
  ? `Revisión necesaria: ${candidato.solicitud_cotizacion.codigo} — ${candidato.proveedor_asociado.nombre}`
  : `${candidato.solicitud_cotizacion.codigo} — ${candidato.proveedor_asociado.nombre}: ${salida.estado.replaceAll('_', ' ')}`;
const mensaje = requiereRevision
  ? `La clasificación automática tuvo una confianza de ${Math.round(confianza * 100)} %. Revisa el correo recibido.`
  : String(salida.razon || evidencia.join(' · ') || 'Se recibió una respuesta del proveedor.');
return [{ json: {
  aplicar, notificar,
  correo: {
    solicitud_id: candidato.solicitud_id,
    proveedor_id: candidato.proveedor_id,
    gmail_message_id: contexto.messageId,
    gmail_thread_id: contexto.threadId,
    remitente: contexto.remitente,
    destinatarios: contexto.destinatarios,
    asunto: contexto.asunto,
    cuerpo_texto: contexto.cuerpo,
    adjuntos: contexto.adjuntos,
    recibido_at: contexto.recibidoAt,
    fuera_plazo: fueraPlazo,
    analisis_agente: salida,
  },
  solicitudId: candidato.solicitud_id,
  proveedorId: candidato.proveedor_id,
  cambios: {
    estado: 'respondio',
    estado_respuesta: salida.estado,
    detalle_respuesta: salida.detalle,
    ultimo_correo_at: contexto.recibidoAt,
    origen_clasificacion: 'agente',
    confianza_clasificacion: confianza,
    evidencia_clasificacion: evidencia,
  },
  aclaraciones: aclaraciones.map((descripcion, indice) => ({
    solicitud_id: candidato.solicitud_id,
    proveedor_id: candidato.proveedor_id,
    dedupe_key: `${contexto.messageId}:${indice}`,
    descripcion,
  })),
  notificacion: {
    usuario_id: candidato.solicitud_cotizacion.creado_por,
    solicitud_id: candidato.solicitud_id,
    proveedor_id: candidato.proveedor_id,
    tipo: requiereRevision ? 'requiere_revision' : 'cambio_respuesta',
    titulo,
    mensaje,
    datos: { estado_propuesto: salida.estado, detalle: salida.detalle, confianza, evidencia, adjuntos: contexto.adjuntos },
    dedupe_key: `correo:${contexto.messageId}`,
  },
}}];

parameters.jsonBody:
={{ { query: `mutation RegistrarRespuesta($correo: correos_proveedor_insert_input!, $solicitudId: uuid!, $proveedorId: uuid!, $cambios: solicitud_proveedores_set_input!, $aclaraciones: [aclaraciones_proveedor_insert_input!]!, $notificacion: notificaciones_insert_input!, $aplicar: Boolean!, $notificar: Boolean!) {
  insert_correos_proveedor_one(
    object: $correo
    on_conflict: { constraint: correos_proveedor_gmail_message_id_key, update_columns: [analisis_agente] }
  ) { id }
  update_solicitud_proveedores_by_pk(
    pk_columns: { solicitud_id: $solicitudId, proveedor_id: $proveedorId }
    _set: $cambios
  ) @include(if: $aplicar) { solicitud_id estado_respuesta }
  insert_aclaraciones_proveedor(
    objects: $aclaraciones
    on_conflict: { constraint: aclaraciones_proveedor_dedupe_key_key, update_columns: [] }
  ) @include(if: $aplicar) { affected_rows }
  insert_notificaciones_one(
    object: $notificacion
    on_conflict: { constraint: notificaciones_dedupe_key_key, update_columns: [] }
  ) @include(if: $notificar) { id }
}`, variables: { correo: $json.correo, solicitudId: $json.solicitudId, proveedorId: $json.proveedorId, cambios: $json.cambios, aclaraciones: $json.aclaraciones, notificacion: $json.notificacion, aplicar: $json.aplicar, notificar: $json.notificar } } }}
